alter table public.shipments add column if not exists transport_mode text, add column if not exists origin_warehouse text, add column if not exists destination_warehouse text, add column if not exists customer_gc_code text, add column if not exists cargo_description text, add column if not exists carton_count integer default 0, add column if not exists actual_weight_kg numeric, add column if not exists length_cm numeric, add column if not exists width_cm numeric, add column if not exists height_cm numeric, add column if not exists volumetric_weight_kg numeric, add column if not exists chargeable_weight_kg numeric, add column if not exists updated_at timestamptz default now();
alter table public.warehouse_receipts add column if not exists photos jsonb default '[]'::jsonb, add column if not exists product_type text, add column if not exists description text, add column if not exists carton_count integer default 0, add column if not exists barcode text, add column if not exists source_warehouse text, add column if not exists customer_name text, add column if not exists created_at timestamptz default now(), add column if not exists notes text;
alter table public.pricing_rates add column if not exists display_name_ku text, add column if not exists display_name_en text, add column if not exists markup_percent numeric default 0, add column if not exists source text;
alter table public.exchange_rates add column if not exists effective_on date default current_date;
create table if not exists public.staff_alerts (id uuid primary key default gen_random_uuid(),kind text not null default 'info',title text not null,body text,entity_type text,entity_id text,action_url text,severity text not null default 'normal',audience_role text,read_by uuid[] default '{}'::uuid[],created_at timestamptz not null default now());
create index if not exists staff_alerts_created_idx on public.staff_alerts(created_at desc);
create index if not exists staff_alerts_entity_idx on public.staff_alerts(entity_type,entity_id);
alter table public.staff_alerts enable row level security;
create table if not exists public.customer_chat_threads (id uuid primary key default gen_random_uuid(),customer_user_id uuid,gc_code text,subject text,status text not null default 'open',priority text not null default 'normal',assigned_staff_id uuid,last_message_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists customer_chat_threads_customer_idx on public.customer_chat_threads(customer_user_id);
create index if not exists customer_chat_threads_gc_idx on public.customer_chat_threads(gc_code);
create table if not exists public.customer_chat_messages (id uuid primary key default gen_random_uuid(),thread_id uuid not null references public.customer_chat_threads(id) on delete cascade,sender_user_id uuid,sender_type text not null default 'customer',body text not null,attachments jsonb default '[]'::jsonb,read_at timestamptz,created_at timestamptz not null default now());
create index if not exists customer_chat_messages_thread_idx on public.customer_chat_messages(thread_id,created_at);
alter table public.customer_chat_threads enable row level security;
alter table public.customer_chat_messages enable row level security;
create table if not exists public.whatsapp_outbox (id uuid primary key default gen_random_uuid(),gc_code text,phone text not null,template_key text,message_body text not null,media_urls jsonb default '[]'::jsonb,shipment_id text,status text not null default 'queued',provider_message_id text,attempts integer not null default 0,last_error text,queued_at timestamptz not null default now(),sent_at timestamptz);
create index if not exists whatsapp_outbox_status_idx on public.whatsapp_outbox(status,queued_at);
alter table public.whatsapp_outbox enable row level security;
create index if not exists finance_transactions_gc_created_idx on public.finance_transactions(gc_code,created_at desc);
create index if not exists pricing_rates_active_lookup_idx on public.pricing_rates(origin_key,destination_key,transport_mode,product_type,is_active,effective_from desc);
create or replace function public.calculate_chargeable_weight(actual_kg numeric,length_cm numeric,width_cm numeric,height_cm numeric) returns numeric language sql immutable as $$ select greatest(coalesce(actual_kg,0),coalesce(length_cm,0)*coalesce(width_cm,0)*coalesce(height_cm,0)/6000.0); $$;